head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > getFrame]<br/>현재 화면을 감싸고 있는 WFrame 객체를 반환합니다.",
    "validation" : [
        "현재 화면을 감싸고 있는 WFrame 객체를 반환해야 합니다.",
        "WFrame 내부가 아닌 전역 스크립트에서 호출하면 null 을 반환해야 합니다. (※ unitTest 환경에서는 최상위 WFrame(mf)이 존재하여 null 검증 불가)",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getFrame_main_onclick = function () {
    var frame = $p.getFrame();

    if (frame !== null) {
        wf_body_bottom.getObj("scwin").setReturnValue("getFrame() : WFrame 객체 반환 (최상위 WFrame)");
        wf_body_bottom.getObj("scwin").setReturnValue("  getOriginalID() : " + frame.getOriginalID());
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("getFrame() : null (WFrame 내부가 아님)");
    }
}



scwin.btn_getFrame_wframe_onclick = function () {
    var frame = wf_test.getObj("$p").getFrame();

    if (frame !== null) {
        wf_body_bottom.getObj("scwin").setReturnValue("wf_test 내부 getFrame() : WFrame 객체 반환");
        wf_body_bottom.getObj("scwin").setReturnValue("  getOriginalID() : " + frame.getOriginalID());
        wf_body_bottom.getObj("scwin").setReturnValue("  getUserData('userData1') : " + frame.getUserData("userData1"));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("wf_test 내부 getFrame() : null");
    }
}
